package com.tripmateai.controller; import com.tripmateai.dto.request.group.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.group.*; import com.tripmateai.service.GroupExpenseService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/trips/{tripId}/group") @RequiredArgsConstructor public class GroupExpenseController {private final GroupExpenseService service; @PostMapping public ResponseEntity<ApiResponse<GroupResponse>> create(@PathVariable Long tripId,@Valid @RequestBody CreateGroupRequest r){return ResponseUtils.created(service.create(tripId,r),"Group created");} @GetMapping public ResponseEntity<ApiResponse<GroupResponse>> get(@PathVariable Long tripId){return ResponseUtils.success(service.get(tripId),"Group retrieved");} @PostMapping("/members") public ResponseEntity<ApiResponse<GroupMemberResponse>> add(@PathVariable Long tripId,@Valid @RequestBody AddGroupMemberRequest r){return ResponseUtils.created(service.add(tripId,r),"Member added");} @DeleteMapping("/members/{userId}") public ResponseEntity<ApiResponse<Void>> remove(@PathVariable Long tripId,@PathVariable Long userId){service.remove(tripId,userId);return ResponseUtils.success(null,"Member removed");} @GetMapping("/expenses") public ResponseEntity<ApiResponse<List<GroupExpenseResponse>>> expenses(@PathVariable Long tripId){return ResponseUtils.success(service.expenses(tripId),"Group expenses retrieved");} @PostMapping("/expenses") public ResponseEntity<ApiResponse<GroupExpenseResponse>> expense(@PathVariable Long tripId,@Valid @RequestBody CreateGroupExpenseRequest r){return ResponseUtils.created(service.createExpense(tripId,r),"Group expense created");} @GetMapping("/balances") public ResponseEntity<ApiResponse<List<GroupBalanceResponse>>> balances(@PathVariable Long tripId){return ResponseUtils.success(service.balances(tripId),"Balances retrieved");} @GetMapping("/settlements") public ResponseEntity<ApiResponse<List<SettlementResponse>>> settlements(@PathVariable Long tripId){return ResponseUtils.success(service.settlements(tripId),"Settlements retrieved");}}
